('SS1', 'science', 'Chemistry', 'Mixtures', 'Which method is most suitable for obtaining salt crystals from a salt solution?', 'Use a magnet to remove the salt', 'Filter the solution through dry sand', 'Evaporate some water and allow the solution to crystallise', 'Separate the salt using a separating funnel', 'C', 'Concentrating the solution and allowing it to cool or evaporate forms salt crystals.', 'medium', '1', 'true'),
('SS1', 'science', 'Chemistry', 'Chemical bonding', 'What type of bond forms when two atoms share a pair of electrons?', 'Ionic bond', 'Metallic bond', 'Hydrogen bond', 'Covalent bond', 'D', 'A covalent bond forms when atoms share electron pairs.', 'medium', '1', 'true'),
('SS1', 'science', 'Chemistry', 'Acids and bases', 'Which salt is formed when hydrochloric acid is completely neutralised by sodium hydroxide?', 'Sodium chloride', 'Sodium carbonate', 'Calcium chloride', 'Sodium sulfate', 'A', 'Hydrochloric acid reacts with sodium hydroxide to form sodium chloride and water.', 'medium', '1', 'true'),

('SS1', 'science', 'Physics', 'Measurement', 'Which instrument is most appropriate for measuring the internal diameter of a narrow tube accurately?', 'Metre rule', 'Stopwatch', 'Spring balance', 'Vernier calipers', 'D', 'Vernier calipers have internal jaws designed for measuring internal diameters.', 'easy', '1', 'true'),
('SS1', 'science', 'Physics', 'Motion', 'A vehicle travels 150 m in 10 s at constant speed. What is its speed?', '15 m/s', '1.5 m/s', '150 m/s', '1,500 m/s', 'A', 'Speed = distance ÷ time = 150 m ÷ 10 s = 15 m/s.', 'easy', '1', 'true'),
('SS1', 'science', 'Physics', 'Force', 'A 4 kg object accelerates at 3 m/s². What resultant force acts on it?', '1.3 N', '12 N', '7 N', '24 N', 'B', 'By Newton’s second law, F = ma = 4 × 3 = 12 N.', 'medium', '1', 'true'),
